import pandas as pd
file_path = '/data/monthly_expense_ledger.xlsx'
df_raw = pd.read_excel(file_path, sheet_name=0, header=None)
header_idx = df_raw[df_raw[0] == 'Transaction ID'].index[0]
rows = []
for i in range(header_idx+1, len(df_raw)):
    row = df_raw.iloc[i]
    tx = row[0]
    if pd.isna(tx):
        continue
    if isinstance(tx, str):
        if tx.strip().isupper() and '2025' in tx:
            continue
        if 'Total' in tx:
            continue
        if tx.startswith('EXP-'):
            rows.append(i)
print("EXP rows indices:", len(rows))
# Check last rows
print(df_raw.iloc[header_idx+1:].tail(50))
